-- Generated by scripts/build_compiled.py from src/fraudrules/rules/foreign-agent/fa-004-payee-without-settlement-profile.yaml. Do not edit.
-- FA-004 MSB pays a foreign company that does not look like a settlement counterparty
SELECT 'FA-004' AS rule_id, 'transactions' AS anchor_table, a.id AS anchor_id
FROM transactions AS a
WHERE (a.direction = 'out' AND a.channel = 'wire' AND a.counterparty_type = 'business' AND a.counterparty_country <> 'us' AND (a.directing_agent_id IS NOT NULL OR a.customer_segment = 'msb') AND (a.counterparty_sector IN ('general_trading', 'textile') OR a.counterparty_web_presence = 0 OR a.ts < (a.counterparty_formed_ts + 15552000)));
